using System; using System.Collections.Generic; using System.Linq; using System.Security.Cryptography; using System.Text; using EngiSentry.Contracts;
namespace EngiSentry.Intelligence { public static class JevSemanticAmbiguityCaseBuilder { public static List<SemanticAmbiguityCase> Build(PlotPlanModel plan){var values=new List<SemanticAmbiguityCase>();foreach(GeometryAssociation a in plan.Geometry.Associations.Where(x=>x.Status=="Ambiguous"&&(x.SubjectKind=="Road"||x.SubjectKind=="Boundary"))){values.Add(Case("geometry|"+a.AssociationId,a.SubjectKind,a.Candidates.Select(x=>x.GeometryKind),a.Candidates.Select(x=>x.SourceLayer),a.LabelRawText,a.Reason,a.Candidates.Count));}foreach(SpatialCoordinateConstraint c in plan.Geometry.SpatialConstraints.Where(x=>x.Status=="Ambiguous"&&(x.SubjectKind=="Road"||x.SubjectKind=="Boundary"))){values.Add(Case("spatial|"+c.ConstraintId,c.SubjectKind,c.Candidates.Select(x=>x.GeometryKind),c.Candidates.Select(x=>x.SourceLayer),c.LabelRawText,c.Reason,c.Candidates.Count));}return values.GroupBy(x=>x.EvidenceId,StringComparer.Ordinal).Select(x=>x.First()).OrderBy(x=>x.EvidenceId,StringComparer.Ordinal).ToList();} private static SemanticAmbiguityCase Case(string localId,string subject,IEnumerable<string> geometry,IEnumerable<string> layers,string? text,string reason,int count){bool road=subject=="Road";return new SemanticAmbiguityCase{EvidenceId=Hash(localId),GeometryKind=geometry.Where(x=>!string.IsNullOrWhiteSpace(x)).OrderBy(x=>x,StringComparer.Ordinal).FirstOrDefault()??string.Empty,LayerName=layers.Where(x=>!string.IsNullOrWhiteSpace(x)).OrderBy(x=>x,StringComparer.Ordinal).FirstOrDefault(),ExistingCandidateKinds=road?new List<string>{JevSemanticLabels.AccessRoadEdge,JevSemanticLabels.Unrelated,JevSemanticLabels.Unknown}:new List<string>{JevSemanticLabels.SecurityFence,JevSemanticLabels.UnitBoundary,JevSemanticLabels.Unrelated,JevSemanticLabels.Unknown},NearbyTextFragments=string.IsNullOrWhiteSpace(text)?new List<string>():new List<string>{text!},SpatialContext=new List<string>{"CandidateCount:"+count.ToString(System.Globalization.CultureInfo.InvariantCulture),"Ambiguity:"+reason},MeasurementBasisHints=road?new List<string>{"AccessRoadEdge"}:new List<string>{"SecurityFence","UnitBoundary"}};} private static string Hash(string value){using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-",string.Empty);}} }
